/* Instructional design: keep the learner at the center. */
const DATA=window.LWM_DATA;
const CONCEPTS=window.COMPASS_CONCEPTS||{};
const IMG={"welcomeHero":"images/welcomeHero.webp","welcomeSecondary":"images/welcomeSecondary.webp","welcomeTertiary":"images/welcomeTertiary.webp","welcomeQuirky":"images/welcomeQuirky.webp","ch1a":"images/ch1a.webp","ch1b":"images/ch1b.webp","ch2a":"images/ch2a.webp","ch2b":"images/ch2b.webp","ch3a":"images/ch3a.webp","ch3b":"images/ch3b.webp","ch4a":"images/ch4a.webp","ch4b":"images/ch4b.webp","ch5a":"images/ch5a.webp","ch5b":"images/ch5b.webp"};
const STORAGE='care-with-a-compass-supervisor-v72-72q'; const LEGACY='care-with-a-compass-supervisor-v63-60q'; const MAX_DECISIONS=20;
const CHAPTERS=DATA.lessons.length, Q=DATA.questions;
const BRANCHING=window.COMPASS_BRANCHING; if(!BRANCHING||BRANCHING.schemaVersion!=='7.2.0')throw Error('Branching data missing: ensure branch data loads before the application'); const FOLLOWUPS=window.COMPASS_QUESTION_FOLLOWUPS||{};
let state=null,storageWorks=true,lastGlossBtn=null;
const ABC='ABCDE';
function fresh(){return {chapter:1,phase:'welcome',history:{},pendingGap:{},wrongTags:{},needsWorkshop:{},maxProgress:{},lab:{},current:null,order:[0,1,2,3,4],lastAnswer:null,reflection:{},refReviewed:{},done:[],capstone:{step:0,choices:[],reflection:'',completed:false},certificateName:'',completedAt:null,streak:{},support:{},guided:false,branchPending:null,branchDone:{},seenConcepts:{},currentConcept:null,labSchedule:{},chapterReporting:{pending:null,status:{}}}}
function load(){try{let a=localStorage.getItem(STORAGE)||sessionStorage.getItem(STORAGE);return a?JSON.parse(a):null}catch(e){try{let a=sessionStorage.getItem(STORAGE)||sessionStorage.getItem(LEGACY);return a?JSON.parse(a):null}catch(_){storageWorks=false;return null}}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(state));storageWorks=true}catch(e){try{sessionStorage.setItem(STORAGE,JSON.stringify(state));storageWorks=true}catch(_){storageWorks=false}}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function chItems(ch){return Q.filter(q=>q.chapter===ch)}
function history(ch){return state.history[ch]||[]}
function unique(ch){return new Set(history(ch).map(x=>x.id)).size}
function latestResults(ch){let map={}; for(const e of history(ch))map[e.id]=e.correct;return map}
// A clean first pass ends after twelve decisions. Unresolved decisions receive targeted practice, then move to live support after the chapter ceiling.
function passes(ch){const map=latestResults(ch);const ids=chItems(ch).map(q=>q.id);return ids.every(id=>map[id]===true)}
function chapterReady(ch){let ready=passes(ch);let capped=history(ch).length>=Math.max(MAX_DECISIONS,chItems(ch).length+8);if(capped&&!ready)state.needsWorkshop[ch]=true;return ready||capped}
function chapterProgress(ch){if(state.done.includes(ch)||chapterReady(ch))return 100;let seen=unique(ch);if(!seen)return 0;let latest=latestResults(ch);let correct=Object.values(latest).filter(Boolean).length;let raw=Math.min(97,Math.round(66*seen/chItems(ch).length+25*correct/chItems(ch).length+6*Math.max(0,history(ch).length-chItems(ch).length)/6));state.maxProgress[ch]=Math.max(state.maxProgress[ch]||0,raw);return state.maxProgress[ch]}
function progressHtml(ch){let v=chapterProgress(ch);return `<section class="chapterprogress" aria-label="Chapter ${ch} progress"><div class="progressline"><span>Chapter progress</span><span>${v===100?'Complete':v===0?'Ready to begin':'In progress'}</span></div><div class="bar" role="progressbar" aria-label="Chapter ${ch} progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${v}"><div class="fill" style="width:${v}%"></div></div><p class="progresshint">${v===100?'Supervisory decisions complete.':'Keep exploring supervisory decisions and evidence.'}</p></section>`}
function nav(){let n=document.getElementById('nav');n.innerHTML=DATA.lessons.map((l,i)=>{const ch=i+1,done=state.done.includes(ch),cur=ch===state.chapter,v=chapterProgress(ch);return `<button type="button" class="navitem ${cur?'current':''} ${done?'done':''}" onclick="openChapter(${ch})" ${cur?'aria-current="step"':''} aria-label="Open Chapter ${ch}: ${esc(l.title)}"><span class="round" aria-hidden="true">${done?'✓':ch}</span><span class="navcopy"><span class="navlabel">${esc(l.title)}</span><span class="navtrack" role="progressbar" aria-label="Chapter ${ch}: ${esc(l.title)} progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${v}"><span class="navfill" style="width:${v}%"></span></span></span></button>`}).join('');if(window.innerWidth<=830){let a=n.querySelector('.navitem.current');if(a){n.scrollLeft=Math.max(0,a.offsetLeft-n.offsetLeft-n.clientWidth/2+a.clientWidth/2)}}}
function openChapter(ch){
 ch=Number(ch);
 if(!Number.isInteger(ch)||ch<1||ch>CHAPTERS)return;
 // Jumping into a chapter never marks it complete or awards assessment credit.
 state.chapter=ch;
 state.current=null;
 state.lastAnswer=null;
 state.selectedMulti=[];
 state.branchPending=null;
 state.chapterReporting.pending=null;
 state.homeFrom=null;
 state.phase='lesson';
 save();
 lesson();
}
function hydratePhotos(){document.querySelectorAll('img[data-photo]').forEach(img=>{const k=img.getAttribute('data-photo');if(IMG[k]){img.src=IMG[k];img.loading='lazy';img.decoding='async';}})}
function navigationTools(){return `<nav class="global-navigation" aria-label="Training navigation"><button class="global-home" type="button" onclick="goHome()" aria-label="Return to home page without losing progress">⌂ <span>Home</span></button><button class="global-restart" type="button" onclick="restart()">↻ <span>Start Over</span></button></nav>`}
function goHome(){state.homeFrom=state.phase;if(window.location.search.includes('embedded=1'))return resume();welcome()}
function allChaptersComplete(){return Array.from({length:CHAPTERS},(_,i)=>i+1).every(ch=>state.done.includes(ch))}
function unsentChapterReminder(){
 if(!window.location.search.includes("embedded=1"))return "";
 const done=(state.done||[]).filter(ch=>state.chapterReporting?.status?.[ch]!=="sent"&&ch!==state.chapterReporting?.pending);
 if(!done.length)return "";
 return `<aside class="chapter-report-reminder"><strong>Chapter reports awaiting submission:</strong> ${done.map(ch=>`<button class="action secondary" type="button" onclick="submitChapterResults(${ch})">Submit Chapter ${ch} Results</button><span id="chapterReminderStatus${ch}" class="chapter-reminder-status">${esc(chapterReportStatusText(state.chapterReporting?.status?.[ch]))}</span>`).join(" ")}<p class="meta">You can submit completed chapters here even after moving ahead for testing.</p></aside>`;
}
function render(content){nav();document.getElementById('main').innerHTML=navigationTools()+unsentChapterReminder()+content;hydratePhotos();let h=document.getElementById('focushead');if(h){h.tabIndex=-1;h.focus({preventScroll:true})}window.scrollTo({top:0,behavior:'instant'});save();window.CWC_CHAPTER_REPORT?.notifyProgress();}
function sourcesHtml(){return `<details><summary>Course readings, California rules and references</summary><p class="meta">Original EDACE 830 supervisor-training demonstration. Class readings and outside references are listed below. Scenarios are fictional composites; requirements depend on license type, jurisdiction, age group and role. This is not legal, clinical or mandated-reporter certification.</p><ul>${DATA.sources.map(x=>`<li>${x[1]?`<a href="${esc(x[1])}" target="_blank" rel="noopener noreferrer">${esc(x[0])}</a>`:esc(x[0])}</li>`).join('')}</ul></details>`}
/* Richard Lawrence Stenlund: judge the situation, not the child. */
const BANNER_SLIDES=[
 {key:'welcomeHero',alt:'Children gathered around a table in an active child care classroom.',caption:'Learning happens in the middle of everyday routines.',position:'center 56%'},
 {key:'welcomeSecondary',alt:'Instructor sharing a guitar lesson with young children in the program.',caption:'Supervisors support the adults who make these experiences possible.',position:'center 46%'},
 {key:'ch3a',alt:'Children and caregivers together on an educational outing at a boardwalk.',caption:'Care extends beyond the classroom. Planning and supervision travel with the group.',position:'center 48%'},
 {key:'welcomeQuirky',alt:'Children watching bubbles fill an indoor play area.',caption:'The ordinary moments matter. So does the leadership behind them.',position:'center 42%'}
];
let bannerIndex=0;
function bannerChange(next){
 const img=document.getElementById('bannerImage'),caption=document.getElementById('bannerCaption');
 if(!img||!caption)return;
 bannerIndex=(next+BANNER_SLIDES.length)%BANNER_SLIDES.length;
 const slide=BANNER_SLIDES[bannerIndex];
 img.src=IMG[slide.key];img.alt=slide.alt;img.style.objectPosition=slide.position;
 caption.textContent=slide.caption;
 document.querySelectorAll('[data-slide-dot]').forEach((b,i)=>{b.setAttribute('aria-current',String(i===bannerIndex));b.setAttribute('aria-label','Show photograph '+(i+1)+' of '+BANNER_SLIDES.length+(i===bannerIndex?', currently selected':''))});
 const status=document.getElementById('bannerStatus');if(status)status.textContent='Photograph '+(bannerIndex+1)+' of '+BANNER_SLIDES.length;
}
function bannerKeydown(event){if(event.key==='ArrowRight'){event.preventDefault();bannerChange(bannerIndex+1)}else if(event.key==='ArrowLeft'){event.preventDefault();bannerChange(bannerIndex-1)}}
function welcome(){state.phase='welcome';bannerIndex=0;render(`
<div class="eyebrow">EDACE 830 · Supervisor leadership · Six learning chapters</div>
<section class="opening-banner welcome-v8-banner" aria-roledescription="carousel" aria-label="Photographs from an early childhood program" onkeydown="bannerKeydown(event)">
<img id="bannerImage" src="${IMG.welcomeHero}" alt="${BANNER_SLIDES[0].alt}" style="object-position:${BANNER_SLIDES[0].position}" decoding="async" fetchpriority="high">
<div class="banner-tint" aria-hidden="true"></div>
<div class="banner-copy"><p class="banner-kicker">The Director's Desk</p><h1 id="focushead">Care with a Compass</h1><p class="banner-subhead">The correct answer is sometimes just the beginning.</p></div>
<div class="banner-controls"><button class="banner-arrow" type="button" onclick="bannerChange(bannerIndex-1)" aria-label="Previous photograph">‹</button><button class="banner-arrow" type="button" onclick="bannerChange(bannerIndex+1)" aria-label="Next photograph">›</button></div>
</section>
<div class="banner-meta"><p id="bannerCaption">${BANNER_SLIDES[0].caption}</p><div class="banner-dots" role="group" aria-label="Choose a photograph">${BANNER_SLIDES.map((slide,i)=>`<button type="button" data-slide-dot="${i}" aria-current="${i===0}" aria-label="Show photograph ${i+1} of ${BANNER_SLIDES.length}" onclick="bannerChange(${i})"></button>`).join('')}</div></div>
<p id="bannerStatus" class="sr-only" aria-live="polite">Photograph 1 of 4</p>
<section class="v8-intro">
<div class="v8-intro-main"><p class="v8-overline">A different kind of supervisor training</p><h2>Real decisions rarely end with one answer.</h2><p>A child goes missing at pickup. A parent challenges your report. A staff member follows the wrong instruction. You may make the right call and still face another problem the next morning.</p><p>Here, you make the decisions. The situation changes. You see the consequences and decide what to do next.</p>
<div class="actions v8-start"><button class="action v8-primary" type="button" onclick="resume()">${state.chapter>1||history(state.chapter).length||state.current?'Continue training':'Begin training'} <span aria-hidden="true">→</span></button><button class="action secondary" type="button" onclick="restart()">Start over</button></div>
<p class="v8-meta">6 chapters · ${Q.length} applied questions · branching decisions · guided practice · final challenge</p></div>
<div class="v8-side-note"><div class="v8-side-head">What to expect</div><div class="v8-step"><strong>01</strong><span>Look at the situation, not just the rule.</span></div><div class="v8-step"><strong>02</strong><span>Choose what you would do as director.</span></div><div class="v8-step"><strong>03</strong><span>Deal with what happens after your decision.</span></div><div class="v8-step"><strong>04</strong><span>Use coaching when you need it. Work toward independence.</span></div></div>
</section>
<section class="v8-footer-note"><strong>Built from real administrative experience.</strong> Scenarios are fictionalized for training. Review current local policies and legal requirements before using a response at work. <span>Learning chapters · Progress preserved</span></section>
${sourcesHtml()}`)}
function resume(){
 const previous=state.homeFrom;state.homeFrom=null;
 if(state.phase==='chapter-submit'&&state.chapterReporting?.pending&&state.done.includes(state.chapterReporting.pending))return chapterSubmissionView();
 if(allChaptersComplete()){
  if(previous==='certificate'||state.phase==='certificate')return window.location.search.includes('embedded=1')?finish():certificateView();
  if(previous==='finished'||state.phase==='finished')return finish();
  return capstone();
 }
 if(state.chapter<1||state.chapter>CHAPTERS||state.done.includes(state.chapter)){
  state.chapter=Array.from({length:CHAPTERS},(_,i)=>i+1).find(ch=>!state.done.includes(ch))||1;
  state.current=null;state.lastAnswer=null;
 }
 if(previous==='followup'&&state.branchPending?.chapter===state.chapter)return branchQuestion();
 if(previous==='lab'&&state.lab?.[state.chapter]?.second===undefined)return trainingLab();
 if(labDue(state.chapter))return trainingLab();
 if(previous==='reflection'||state.phase==='reflection'||chapterReady(state.chapter))return reflection();
 if(state.current&&Q.some(q=>q.id===state.current&&q.chapter===state.chapter))return showQuestion();
 return lesson();
}
function restart(){if(confirm('Start over? This clears your saved training progress and begins again at Chapter 1.')){state=fresh();if(window.location.search.includes('embedded=1'))lesson();else welcome()}}
/* Richard Lawrence Stenlund: language should open doors. */
function glossary(text){
 // One pass through visible text only. Never search within HTML attributes or a newly inserted tooltip.
 const terms=Object.entries(DATA.glossary).sort((a,b)=>b[0].length-a[0].length);
 const seen=new Set();
 const escaped=terms.map(([term])=>term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));
 const pattern=new RegExp('\\b('+escaped.join('|')+')(?:s|es)?\\b','gi');
 return text.split(/(<[^>]+>)/g).map(segment=>{
   if(segment.startsWith('<'))return segment;
   return segment.replace(pattern,(full)=>{
     const lower=full.toLowerCase();
     const entry=terms.find(([term])=>lower===term.toLowerCase() || lower===term.toLowerCase()+'s' || lower===term.toLowerCase()+'es');
     if(!entry || seen.has(entry[0]))return full;
     const [term,def]=entry;
     seen.add(term);
     return `<button class="glossbtn" type="button" data-definition="${esc(def)}" data-term="${esc(term)}" aria-label="${esc(full)}. Definition available" aria-expanded="false" onclick="showGloss(this.dataset.term,this)">${esc(full)}<span class="glosshint" aria-hidden="true">?</span></button>`;
   });
 }).join('');
}
function positionGloss(){
 const g=document.getElementById('glossary');
 if(!g||g.hidden||!lastGlossBtn||!lastGlossBtn.isConnected)return;
 const rect=lastGlossBtn.getBoundingClientRect(),gap=10,pad=12;
 const width=g.offsetWidth,height=g.offsetHeight;
 const vw=document.documentElement.clientWidth,vh=window.innerHeight;
 const left=Math.max(pad,Math.min(rect.left,vw-width-pad));
 let top=rect.bottom+gap;
 if(top+height>vh-pad){
   top=rect.top-height-gap>=pad?rect.top-height-gap:Math.max(pad,vh-height-pad);
 }
 g.style.left=Math.round(left)+'px';
 g.style.top=Math.round(top)+'px';
}
function showGloss(term,btn){
 const g=document.getElementById('glossary');if(!g)return;
 if(lastGlossBtn&&lastGlossBtn!==btn)lastGlossBtn.setAttribute('aria-expanded','false');
 lastGlossBtn=btn;
 btn.setAttribute('aria-controls','glossary');btn.setAttribute('aria-expanded','true');
 g.classList.add('gloss-popover');g.setAttribute('role','dialog');
 g.hidden=false;
 g.innerHTML=`<strong>${esc(term)}</strong><p>${esc(DATA.glossary[term])}</p><button class="action secondary" type="button" onclick="closeGloss()">Close definition</button>`;
 document.body.classList.add('gloss-open');
 positionGloss();
 g.focus({preventScroll:true});
}
function closeGloss(restoreFocus=true){
 const g=document.getElementById('glossary');if(g)g.hidden=true;
 document.body.classList.remove('gloss-open');
 if(lastGlossBtn){lastGlossBtn.setAttribute('aria-expanded','false');if(restoreFocus&&lastGlossBtn.isConnected)lastGlossBtn.focus({preventScroll:true})}
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.glossbox.gloss-popover:not([hidden])')){e.preventDefault();closeGloss()}});
document.addEventListener('pointerdown',e=>{
 const g=document.getElementById('glossary');
 if(g&&!g.hidden&&!g.contains(e.target)&&!e.target.closest('.glossbtn'))closeGloss(false);
});
window.addEventListener('resize',positionGloss);
window.addEventListener('scroll',()=>{
 const g=document.getElementById('glossary');
 if(g&&!g.hidden)positionGloss();
},{passive:true});
function lensHtml(ch){
 const entries=(DATA.lensCases||[]).map((item,index)=>({item,index})).filter(entry=>entry.item.chapter===ch);
 if(ch===1||!entries.length)return '';
 return entries.map(({item,index})=>`<details class="lens"><summary>Try another angle: ${esc(item.title)}</summary><p>${esc(item.situation)}</p><p><strong>What would you ask first?</strong> ${esc(item.question)}</p><button class="action secondary" type="button" aria-expanded="false" onclick="showLens(this,${index})">Consider both perspectives</button><div class="lenscompare" hidden></div></details>`).join('');
}
function showLens(btn,index){
 const item=DATA.lensCases?.[index],el=btn.nextElementSibling;
 if(!item||!el)return;
 const expanded=!el.hidden;
 el.hidden=expanded;
 btn.textContent=expanded?'Consider both perspectives':'Hide the perspectives';
 btn.setAttribute('aria-expanded',String(!expanded));
 if(!expanded)el.innerHTML=`<div class="perspectives"><div><strong>Staff, child, or family perspective</strong><p>${esc(item.employee)}</p></div><div><strong>Leadership or program perspective</strong><p>${esc(item.supervisor)}</p></div></div><p class="meta">Ask questions and check the facts before making a decision.</p>`;
}

// Version 8: support before the decision, then gradual fading across chapters.
const CHAPTER_GUIDES={
 1:{example:'A caregiver makes a troubling remark. First ensure that children are safe and appropriately supervised. Next gather facts without assuming that one statement proves misconduct. Then document what you know and decide what follow-up is fair.',prompt:'What do you know for certain? What needs immediate attention? What facts are still missing?'},
 2:{example:'A child discloses a concern. Separate immediate protection from your reporting duties. Record the child\'s words accurately; do not conduct your own investigative interview. Follow applicable reporting requirements.',prompt:'What must happen promptly? Which information should be documented, and what belongs to the appropriate authorities rather than your own investigation?'},
 3:{example:'A staff member arrives late. Confirm actual coverage and supervision first, keep truthful records, and then make a workable plan to prevent a repeat. A paper schedule does not replace a qualified adult.',prompt:'What is actually happening in the room? What do the records show? Who is authorized to act?'},
 4:{example:'During an emergency, act on immediate safety needs, use the child\'s documented plan where applicable, coordinate roles and keep accurate records. After the immediate danger, address the next problem.',prompt:'What takes priority in the next minute? What must be verified before you delegate?'},
 5:{example:'A repeated near miss points to a system problem. Find the pattern, involve the people affected, test a correction, and check whether the change actually works.',prompt:'What pattern is emerging, and how would you know your response prevented a repeat?'}
};

const DEEPER_LESSONS={"1":{"title":"Why a supervisor responds to the system, not just the employee","body":["A concerning remark, an inaccurate record, or a staff conflict may look like an individual attitude problem. Before deciding on discipline, a director must separate immediate child protection from what is actually known about the employee's conduct. Reassigning someone temporarily to protect children can be justified without pretending that the allegation has already been proven.","The next question is whether the system encouraged the mistake. Did another employee give contradictory instructions? Was adequate staffing available? Did the supervisor model the correct behavior or simply tell the aide to be more careful? A leader should correct the immediate risk, preserve original records, give an opportunity for a fair response, and verify improvement through direct observation.","Leadership decisions create secondary consequences, including family distrust, staff defensiveness and potential turnover. Evaluate your decision not only by whether the immediate problem disappeared but by whether children remained safe and the underlying practice changed."],"question":"After an appropriate first response, what new problem could your own decision create?"},"2":{"title":"Why evidence, reporting and fairness must coexist","body":["A mandated reporter does not need proof before making a legally required report based on reasonable suspicion. Waiting for an employee confession, a perfectly clear video, or a family's agreement can undermine a timely report. The director still needs to protect children immediately and avoid turning the facility into its own investigative agency.","An allegation is not the same as a verified finding. Preserve video in its original form, identify exactly who saw what, record spontaneous statements accurately and limit dissemination. A report should not become a public accusation. Staff and families deserve factual process updates within confidentiality boundaries.","Consider the consequences of both underreaction and overreaction. A delay can leave children at risk; a careless accusation can damage a family or employee without adding safety. Sound judgment is procedural: protect, report when required, preserve evidence, and cooperate with the appropriate agency."],"question":"Which facts create a legal duty now, and which remain unverified?"},"3":{"title":"Why a posted schedule is not real coverage","body":["Ratios are calculated from children present and qualified staff actually available for their assigned duties, subject to the specific program and license rules. A teacher who is in an ambulance or handling a separate emergency cannot be counted in two places. Equally, a volunteer's experience does not automatically mean the person meets the licensing qualifications.","Practice checking each transition: pickup, outdoor play, lunch, an unexpected absence, and an emergency. When qualified coverage is not available, a director must change the activity, move children only after checking the receiving space, use an eligible relief staff member, or limit intake. No amount of persuasive leadership can turn a missing qualified employee into adequate supervision.","The second-order problem is financial and operational. Reliable backup coverage costs money. A responsible program plan includes that cost and measures actual coverage events, not only whether a form was signed."],"question":"What would you verify before asking one teacher to leave a classroom?"},"4":{"title":"Why emergency judgment must continue after the first response","body":["Emergency care starts with the child's observed condition and individualized plan, not the convenience of a parent pickup. Trained staff should assess warning signs and activate emergency help when warranted while another qualified adult keeps the remaining children supervised. For an alert child with an uncomplicated nosebleed, forward positioning and continuous pressure are supported by first-aid guidance; severe symptoms or significant injury can change that response.","Once help is underway, verify the handoff: who has essential medical information, who has authority to consent or arrange release, who is contacting family, and what is happening back at the facility? Avoid diagnosing, guessing at neglect, or assuming a director automatically acquires parental authority.","A sound initial decision may still result in a worsening condition or a complaint. Learn to reassess and document carefully without equating an unfavorable outcome with a preventable mistake. Strong supervision is shown by how decisions adapt when the facts change."],"question":"What must be reassessed when the child seems better but another risk appears?"},"5":{"title":"Why a successful training score is not proof of changed practice","body":["Training attendance, correct quiz answers and completed checklists can show exposure to instruction. They do not establish whether a director will carry out the right actions under pressure. To evaluate transfer, look for demonstrations using unfamiliar situations, realistic constraints and follow-up observations in the workplace.","A good evaluator separates the learner's decision process from outcomes beyond their control. A complaint may follow a sound safeguarding decision; a child may improve despite a poor initial choice. Scoring should reflect the evidence and standards available at the moment, and safety-critical errors should not be erased by a high aggregate percentage.","Use evaluation to revise the program, not merely to certify completion. Collect feedback about confusing instructions, identify recurring decision gaps, provide tailored rehearsal and verify whether the new behavior persists after 30 or 60 days. This is how program planning becomes accountable professional development."],"question":"What evidence would show a participant can transfer this lesson to a new situation?"},"6":{"title":"Equity is verified in decisions, not claimed in policy","body":["Equal expectations do not mean mechanically identical outcomes. Staff must respond to individual safety facts and support needs, while directors ensure that differences in discipline and family communication have an evidence-based reason rather than a stereotype.","A disparity in records can be a signal to investigate, but it does not alone prove intentional bias. Review observed behavior, context, staff actions, opportunity to participate, and the actual support offered. Small groups and different attendance patterns can also affect rates.","Make adult learning observable: use neutral notes, observe comparable situations, invite family context without blame, provide feedback privately, and review whether later reports and exclusion decisions changed. A respectful policy without consistent practice will not protect children."],"question":"What would you find in the next 30 days that proves the child was treated fairly, rather than simply receiving less negative paperwork?"}};
function deeperLessonHtml(ch){const d=DEEPER_LESSONS[ch];if(!d)return '';return '<div class="card" style="margin-top:18px;background:#f8f6fb"><h3>'+esc(d.title)+'</h3>'+d.body.map(p=>'<p>'+esc(p)+'</p>').join('')+'<p><strong>Director\'s reflection:</strong> '+esc(d.question)+'</p></div>';}
function followupTeachingHtml(node,chosen,origin){const q=Q.find(x=>x.id===origin),v=node.options[chosen],best=node.options.find(x=>x.level===2)||node.options[0],ch=q?.chapter||state.chapter,d=DEEPER_LESSONS[ch];let x='<div class="card" style="background:#f8f6fb"><h3>Why the next decision matters</h3>';x+='<p><strong>Underlying principle:</strong> '+esc(q?.rationale||'Assess current facts and the relevant duty before you act.')+'</p>';if(v.level===2)x+='<p><strong>Why this response works:</strong> It addresses the new development while maintaining an essential duty from the original incident. A sound decision can still produce an unforeseen result, so reassess instead of assuming the matter is finished.</p>';else x+='<p><strong>Why your response needs revision:</strong> '+esc(v.level===1?'It deals with part of the new problem, but leaves a safety, evidence, communication or supervision requirement unresolved.':'It leaves an essential risk uncontrolled or treats an unverified assumption as an established fact.')+'</p><p><strong>A safer next move:</strong> '+esc(best.text)+'</p>';x+='<p><strong>Transfer this learning:</strong> '+esc(d?.question||'What would you verify in a similar incident?')+'</p><p class="meta">Compare your reasoning with the linked standards. Mandatory duties and recommended strategies are not interchangeable.</p></div>';return x;}

const CHAPTER_STUDY_GUIDES={"1":[{"ids":"C1Q01 C1Q06","title":"Immediate child protection versus personnel discipline","body":"A troubling employee statement and a sleep-deprived or visibly distressed caregiver call for a prompt assessment of whether children can receive safe, respectful care right now. Do not equate an alarming remark with proof of abuse or automatically impose final discipline. Arrange qualified relief when necessary, identify what was observed, hear the employee's account privately, and use documented policy to decide whether coaching, reassignment, leave or a formal personnel response is justified. A director can protect children immediately without claiming to have resolved the facts."},{"ids":"C1Q02 C1Q03 C1Q08","title":"Attendance accuracy, consistent instructions and handoffs","body":"A sign-in or handoff error is not just a paperwork problem: it can conceal who was responsible for a child, when that responsibility changed, or whether medicine information was transferred. Never invent, backdate or quietly erase an original attendance entry. Verify real times using reliable evidence; make a transparent, dated correction; and compare the instructions different supervisors gave. Demonstrate the approved handoff, use teach-back, then inspect later entries. When staff challenge documentation requirements, explain their child-safety purpose instead of treating every objection as insubordination."},{"ids":"C1Q04 C1Q05","title":"Fair workload, accommodation and cross-room relief","body":"A high performer calling another employee 'lazy' has described an interpretation, not a fact. Observe duties and support needs, compare assignments, and ask whether one employee repeatedly carries a more demanding workload. When a dependable teacher needs a predictable schedule adjustment, verify qualified coverage for both the room they leave and the room lending the floater. A workable arrangement may be piloted and rechecked; consent from coworkers alone cannot replace required child coverage. Address both fairness and organizational consequences rather than rewarding whoever complains most forcefully."},{"ids":"C1Q07 C1Q11 C1Q12","title":"Privacy, bodily boundaries and respectful family conflict","body":"Private staff groups are not automatically authorized places to circulate images of children. Check each child's applicable consent, audience, and approved media policy before recording or sharing identifiable information. A child seeking affection and an educator setting personal boundaries both deserve dignity; offer an age-appropriate, nonshaming alternative and develop consistent staff practices. With an angry parent, establish behavior expectations and protect employees, but distinguish a genuine threat from an unpleasant disagreement. Document the conduct and choose proportional responses rather than immediately ejecting a family without reviewing facts and obligations."},{"ids":"C1Q09","title":"An experienced substitute is not automatically eligible coverage","body":"Professional experience, personal recommendations and a completed orientation do not themselves establish that a substitute can count toward a particular licensed teacher-child ratio. Verify qualifications, required clearances, permitted duties, and assignment-specific orientation before leaving children in their care. If eligibility cannot be verified, maintain existing qualified coverage or adjust intake instead of relying on the substitute to solve a staffing emergency. Record what was verified and what still requires follow-up."},{"ids":"C1Q10","title":"Behavior observations without labeling the child","body":"When an educator labels an autistic child's distress 'bad behavior,' ask what was happening before the event, how the child communicated, which supports were available, and what followed. A frequency count alone may not explain the reason for distress. Collect objective observations, consult the child's individualized plan and relevant professionals, coach staff in supportive de-escalation, and evaluate whether the environment or routine should change. Effective leadership avoids confusing a child's disability-related needs with an employee's lack of training, staffing capacity or policy failure."}],"2":[{"ids":"C2Q01 C2Q04 C2Q07 C2Q12","title":"Reasonable suspicion, protective action and separate reports","body":"California's mandated-reporting duty uses reasonable suspicion, not proof beyond doubt. When facts establish that threshold, a mandated reporter follows the required reporting process without first obtaining an employee confession, conducting repeated child interviews or waiting for a video timestamp. In parallel, immediately protect children, use neutral interim staffing arrangements, preserve original evidence and evaluate any separate child care licensing incident-reporting duty. A suspected-abuse report and a licensing incident report are not interchangeable: their triggers, recipients and timing can differ. Document exact spontaneous statements, not an investigative script."},{"ids":"C2Q02 C2Q10","title":"Poverty, housing instability and evidence of actual harm","body":"Poverty, homelessness, an unmet uniform expectation or a parent seeking schedule flexibility is not itself proof of neglect. Look at the child's actual condition and supervision, the seriousness and persistence of any danger, and what support can be offered. If observed conditions create reasonable suspicion, do not withhold a required report merely because the family faces hardship. A director can respond compassionately to barriers and still fulfill a legal safeguarding duty. Record concrete conditions rather than socioeconomic labels."},{"ids":"C2Q03 C2Q06 C2Q11","title":"Retaliatory allegations, evidence preservation and confidentiality","body":"A complaint that follows a report or personnel intervention may be upsetting, but its timing does not prove it is false or retaliatory. Respond to each stated concern with a factual investigation, maintain safe interim operations and cooperate with investigators. Preserve original footage, logs and witness accounts with their corrections. Share a limited process or safety update with people entitled to know; do not publish accused employees' confidential records or tell other families that an allegation proves wrongdoing. A complaint and a substantiated violation are different stages."},{"ids":"C2Q05","title":"Gender bias and equitable professional boundaries","body":"A family may express discomfort with a male caregiver despite no evidence of inappropriate care. Listen to the specific concern and explain staff authorization, safeguarding practices and consistent duties without declaring that every personal preference is legally decisive. Protect the employee from arbitrary exclusion while considering reasonable, lawful arrangements for children and families. Avoid a policy that shifts all intimate-care or emotionally demanding duties to one sex without considering fairness and child-specific needs."},{"ids":"C2Q08 C2Q13 C2Q14","title":"Images, outside consultants and classroom inspection privacy","body":"A legitimate training or observation goal does not create blanket permission to distribute a child's identifiable video or voice. Check the actual consent, authorized purpose, recipient and retention safeguards before sharing. During a family classroom inspection, lawful observation rights coexist with every child's privacy and safety; they do not grant a visitor unlimited authority to interview unrelated children, record them or distribute images. Stop an inappropriate interaction, maintain supervision, preserve evidence and consider the correct notification process without automatically labeling the event child abuse."},{"ids":"C2Q09","title":"Verifying identity and release authority","body":"Biological relationship, a familiar nickname or a convincing identification card may be relevant but do not by themselves establish current release authority. Check enrollment authorization and relevant court documents, authenticate any new direction through a trusted contact method, and maintain supervision while uncertainty is resolved. Do not release a child based only on an unverified caller or a visitor's assertion. If there is an immediate threat, prioritize entry security and emergency response."}],"3":[{"ids":"C3Q01 C3Q02 C3Q12 C3Q17 C3Q18","title":"Live ratios, qualified coverage and age-specific staffing rules","body":"Count the children actually present and adults actually eligible and available for the assigned license category. California Title 22 preschool, toddler, school-age and infant rules are not interchangeable, and aides may have different allowable roles from qualified teachers. Under the basic preschool teacher-child model, moving from 12 to 13 children changes the minimum number of teachers required unless another lawful staffing configuration applies. A director counts only while actually performing qualifying supervision duties. A substitute, floater or borrowed staff member must be eligible for that room; an employee cannot be counted in two rooms after leaving one. If coverage falls short, obtain real qualified relief or change intake and activities. Never falsify time records to create apparent compliance."},{"ids":"C3Q03 C3Q08","title":"Licensed capacity is separate from staff ratio","body":"A classroom may appear to meet the numeric teacher-child ratio and still exceed the license's authorized capacity, age range, room allocation or other conditions. Before promising an additional place, verify the facility license, classroom use, children present, qualified staff and any permitted exceptions. A second room does not become legal merely because its total head count looks workable on paper. If enrollment expectations conflict with actual capacity, correct the promises and provide safe alternatives rather than quietly exceeding authorization."},{"ids":"C3Q04 C3Q06 C3Q11","title":"Sanitation, food safety and accessible hazards","body":"A broken water supply affects toilets, handwashing, food preparation and the ability to operate safely. Bottled drinking water alone may not restore required sanitation; activate the emergency plan, determine whether safe operation is feasible and arrange pickup, approved relocation or other lawful action if needed. Food labels also matter differently: a manufacturer's 'use by' date on infant formula is not the same issue as a quality-oriented 'best if used by' label on a shelf-stable product. Follow applicable handling rules and the child's needs. An accessible chemical, broken gate or missing emergency information requires prompt correction rather than merely another reminder memo."},{"ids":"C3Q05 C3Q10","title":"Inclusive evacuation and field-trip planning","body":"An evacuation plan that assumes every child follows shouted directions has not been tested for children with mobility, sensory or communication needs. Assign specific trained adults, rehearse alternate routes, and verify that the plan works under realistic noise and staffing conditions. On outings, follow individualized elopement or medical plans, confirm vehicle and staffing duties, verify transitions with head counts, and avoid using a tracker or a familiar caregiver as the sole safeguard. Inclusion requires adapting the environment and procedure, not automatically excluding the child."},{"ids":"C3Q07","title":"Real-time sign-out integrity and a traceable correction trail","body":"A nickname, a missing departure time or a promise to fill the log later undermines accountability for when a child was released. Record verified authorization, the actual departure event and the responsible handoff. If the entry is wrong, retain an auditable original and correction rather than overwriting history to make records look neat. Train everyone who performs release duties and audit the next few transitions rather than assuming one correction solved the system problem."},{"ids":"C3Q09 C3Q13 C3Q14","title":"Lawful inspections, verification and active supervision","body":"Verify an unexpected licensing analyst's identity through an appropriate official method while cooperating with lawful regulatory access. Parent inspection rights are not the same as permission to obstruct supervision, interrogate unrelated children or remain indefinitely as a waiting-room guest in active classrooms. Use administrative coverage, appropriate observation arrangements and factual communication so qualified teachers remain responsible for their groups. Do not impose arbitrary blanket appointment requirements where unannounced lawful inspections must be permitted."},{"ids":"C3Q15 C3Q16","title":"Authorized pickup, threatening visitors and changed permissions","body":"When a threatening or unlisted person appears, keep entry secure and the child supervised, verify release authority through actual records, and use emergency help when the threat warrants it. A child's use of 'Daddy' or a familiar caller ID cannot replace authorization. For last-minute pickup changes, use an authenticated written or otherwise policy-compliant method, independently verify through a trusted contact, check identity and document the release. Where verification fails, maintain care until an eligible adult can be established."}],"4":[{"ids":"C4Q01 C4Q07 C4Q11","title":"Ambulance handoff, parent unavailability and continuity of care","body":"Medical responders handle urgent clinical decisions within their roles. The director coordinates factual information, the child's plan, authorized contacts and qualified supervision of the children who remain. A parent refusing or missing a hospital call does not automatically transfer parental medical authority to the director or automatically prove neglect. Use established emergency authorization and escalation procedures, seek hospital social-work or other appropriate assistance when necessary, and record what was actually said. Late pickup likewise requires a supervised, documented escalation pathway, not an unauthorized release or abandonment."},{"ids":"C4Q02 C4Q05","title":"Seizure plans and unbiased emergency communication","body":"When a child with a documented seizure disorder becomes unresponsive, staff should act according to the child's current individualized emergency plan and indicated urgent symptoms. Observe breathing, responsiveness, duration and recovery, and obtain emergency help when the plan or clinical danger calls for it. A clinician needs a precise timeline and baseline information, not stigmatizing descriptions such as 'difficult' or assumptions about disability. Record objective behavior and supports, communicate accessibly and protect the child's dignity."},{"ids":"C4Q03 C4Q09","title":"Allergy plans, suspected exposure and substitute preparation","body":"Potential allergen exposure may require immediate action when symptoms suggest a serious reaction; do not wait for a parent to confirm what to do if the child's emergency plan and clinical signs require prompt response. Check the specific action plan, medication readiness, food authorization and personnel trained to act. Before a substitute supervises meals, ensure they understand the allergies and emergency steps. A general allergy reminder cannot substitute for the individual child's documented protections."},{"ids":"C4Q04","title":"Medication orders, consent and staff authorization","body":"A parent's text may provide useful information but does not necessarily meet the documentation, order, consent or trained-staff requirements applicable to medication administration. Verify the child's specific instructions and the authorized person who may administer the medication. If the child has urgent clinical needs, seek appropriate medical guidance or emergency assistance instead of either giving an unverified dose or ignoring the emergency. Keep the medication secure and document the verified decision path."},{"ids":"C4Q06 C4Q10","title":"Accessibility in emergencies and elopement prevention","body":"Safety plans must work when a substitute arrives or the usual staff member is absent. Train and rehearse individual elopement and evacuation supports, ensure exits are usable, keep gates secured and confirm exactly who supervises the child during transitions. A child remaining safe by luck after an unlatched gate is a near miss worth analyzing. During an emergency, an obstructed accessible exit is a current operational hazard, not a detail to fix at the next meeting."},{"ids":"C4Q08","title":"Symptoms outrank reassuring labels and convenience","body":"A child who is afebrile can still be seriously ill. Assess current responsiveness, breathing, weakness and the child's usual baseline rather than assuming the absence of a fever means the child may remain in routine activities. Seek urgent clinical advice or emergency help according to observed signs and documented plans. Family preference is valuable information but does not replace necessary protective action."},{"ids":"C4Q12 C4Q13 C4Q14","title":"Missing-child near misses, secure entry and release verification","body":"A child briefly missing at a field-trip handoff is a serious supervision concern even when the child is found unharmed. Reconstruct the actual timeline, preserve the roster and verify whether licensing reporting thresholds apply. A threatening unlisted adult at a locked entrance calls for physical security, protecting children from opening exits and appropriate escalation. After any unauthorized pickup, verify how instructions were authenticated, preserve original records, and redesign the handoff instead of merely giving the staff another generic quiz."}],"5":[{"ids":"C5Q01","title":"Employee attendance, backup staffing and sustainable accountability","body":"Repeated lateness requires a credible response to its effect on coverage, not merely an empathy conversation or automatic punishment. Verify actual work times and safety impact, listen for predictable transportation or family barriers, and establish the employee's performance expectations. Arrange qualified relief before the next absence, monitor whether the revised plan works and avoid paying for an apparent staffing solution by placing extra duties on an already exhausted coworker."},{"ids":"C5Q02 C5Q07 C5Q09","title":"Disability-affirming support, AAC and safe de-escalation","body":"Distress should be understood through triggers, communication needs, environmental demands and the individualized plan rather than by labeling the child intentionally disruptive. Ensure the child's communication device remains available during routines and substitutions. Coach staff to use compatible supports and de-escalation, then observe whether changes reduce risk. Do not impose isolation, denial of communication, or deprivation of basic support as a shortcut to classroom control. Safety and dignity must coexist."},{"ids":"C5Q03 C5Q04 C5Q10","title":"Coordination across settings and equitable participation","body":"A child whose school and child care settings disagree about emergency medication needs an authorized, documented plan specifying who is responsible, what approvals exist and what happens while the issue is unresolved. A child who needs AAC, additional supervision or accessible transportation should not automatically be excluded from a field trip. Assess the individual needs, reasonable modifications, staffing feasibility and safety plan. Record which resources are required and distinguish a fixable access barrier from an actual safety limitation."},{"ids":"C5Q05 C5Q08","title":"Why training attendance and satisfaction are not enough","body":"A high satisfaction rating, completed checklist or signed training log cannot prove that staff perform the necessary action during an unexpected event. Use direct observation, unfamiliar role-play, repeated checks and reviews of actual handoffs to see whether learning transferred. When the same hazard appears again, diagnose whether the cause was instruction, unclear ownership, inadequate tools, unstable staffing or ineffective follow-up. Correct the system and verify sustained change rather than simply repeating the same online module."},{"ids":"C5Q06 C5Q11 C5Q12","title":"Assessment design that tests transfer, not memorization","body":"A learner can earn excellent quiz scores by recognizing wording patterns without making sound real decisions. Use new scenarios, competing plausible responses, changing facts, observed demonstrations and follow-up evidence. Score the safety-critical process separately from results the learner cannot fully control. When an assessment exposes recurring gaps, redesign the learning activities to address them and measure improvement in the workplace. Do not mistake a certificate for proof of competent leadership."},{"ids":"C5Q13","title":"Media privacy and corrective action after an unauthorized post","body":"Before public sharing, verify consent and every identifiable child in the image, including those in the background. Once an unauthorized post appears, prevent continued exposure, preserve the relevant record, notify affected people as appropriate, review reporting duties and correct the approval process. A private setting or cropped image may reduce future disclosure but does not necessarily repair the original mistake. Focus on both immediate protection and the workflow that allowed the post."},{"ids":"C5Q14","title":"Parent inspection rights with respectful conduct limits","body":"An effective policy distinguishes lawful observation from conduct that threatens supervision or other children's privacy. Blanket fixed-hour or advance-notice requirements can conflict with applicable parent inspection rights. Maintain appropriate entry security and actual supervision, provide lawful access, and develop conduct-based procedures rather than banning inconvenient observation. Train staff using specific examples and verify the revised process under realistic arrival conditions."}]};
function topicForQuestion(qid){for(const [chapter,rows] of Object.entries(CHAPTER_STUDY_GUIDES))for(let i=0;i<rows.length;i++)if(rows[i].ids.split(" ").includes(qid))return {chapter:Number(chapter),index:i,title:rows[i].title};return null;}
function studyGuideHtml(ch){const entries=CHAPTER_STUDY_GUIDES[ch]||[];if(!entries.length)return '';return '<section class="card" id="chapter-study-guide" aria-label="Chapter field guide" style="margin-top:20px"><h2>Director\'s field guide: apply these ideas</h2><p>Use these principles while considering the chapter decisions. The examples teach the reasoning, not an answer pattern to memorize.</p>'+entries.map((row,i)=>'<section class="study-topic" id="studytopic-'+ch+'-'+i+'" style="border-top:1px solid #d8d0df;margin-top:18px;padding-top:12px"><h3>'+esc(row.title)+'</h3><p>'+esc(row.body)+'</p></section>').join('')+'</section>';}
function openStudyGuideFor(qid){const topic=topicForQuestion(qid),panel=document.getElementById("chapter-review");if(!topic||!panel)return;panel.open=true;let target=document.getElementById("studytopic-"+topic.chapter+"-"+topic.index);if(target){target.scrollIntoView({block:"start",behavior:"smooth"});target.setAttribute("tabindex","-1");target.focus({preventScroll:true});}}
function workedExampleHtml(ch){
 if(ch===1)return '';
 const g=CHAPTER_GUIDES[ch];if(!g)return '';
 return `<details class="v8-worked-example" ${ch<=2?'open':''}><summary>A director's approach</summary><p>${esc(g.example)}</p><p class="meta">Check current rules and the child's care plan.</p></details>`;
}
function decisionGuideHtml(ch){
 const g=CHAPTER_GUIDES[ch];if(!g)return '';
 if(ch===5)return '<p class="v8-independent"><strong>Independent practice.</strong> There is no pre-decision guide in this chapter. Work through the situation using what you have learned. Feedback follows your choice.</p>';
 if(ch===4)return `<details class="v8-guide"><summary>Need a nudge? Open a reflection prompt</summary><p>${esc(g.prompt)}</p></details>`;
 if(ch===3)return `<details class="v8-guide"><summary>Need a hint?</summary><p>${esc(g.prompt)}</p></details>`;
 return `<details class="v8-guide" open><summary>Before you choose</summary><p>${esc(g.prompt)}</p><p class="meta">You will get less guidance as you progress.</p></details>`;
}

// Two connected, changing-facts decisions per chapter. All people and settings are fictionalized instructional composites.
const LABELS={2:'Most complete response',1:'Defensible, with conditions',0:'Reconsider the trade-off'};
const TRAILS={"1":{"title":"The missing child at pickup","intro":"At the end of the day, a parent arrives to collect her child. The attendance sheet shows that the child was signed out 15 minutes ago, but the parent says nobody picked her up. The new teacher says another staff member told her to complete sign-out entries before families arrived. The child is still safely in the classroom.","first":{"prompt":"What should the director do first?","options":[{"text":"Confirm the child is safe, correct the inaccurate record, and find out who instructed staff to sign children out early.","level":2,"why":"The child is safe, but the false departure time is a serious accountability problem. Address the record immediately and investigate how the instruction arose."},{"text":"Ask the parent to sign the child out now, then review the recordkeeping process with the team before the next pickup period.","level":1,"why":"This addresses the immediate handoff, but it leaves the false entry and its cause insufficiently documented and investigated."},{"text":"Keep the original entry because changing attendance records after the fact could create questions during an inspection.","level":0,"why":"Knowingly leaving an inaccurate entry in place compounds the problem. Corrections should be transparent and traceable."},{"text":"Send the teacher home for the day and ask the most experienced staff member to handle sign-outs.","level":0,"why":"Removing the teacher may be necessary in some circumstances, but it does not establish why the record was falsified or repair the current entry."}]},"follow":{"lead":"The director learns that two shift leads gave opposite instructions: one said to record the actual departure time, while the other told staff to fill in times early to speed up pickup. Another parent now asks whether the facility can prove exactly when her child left yesterday.","prompt":"How should the director respond to the new problem?","options":[{"text":"Preserve the original entries and correction history, review yesterday’s handoff evidence, retrain both shift leads on one written procedure, and explain verified facts to the parent.","level":2,"why":"This protects record integrity, addresses the parent’s concern without guessing, and fixes the conflicting instructions."},{"text":"Review yesterday’s records with the parent, then remind staff at the next meeting to be more careful.","level":1,"why":"Reviewing the concern is reasonable, but a general reminder is inadequate when supervisors have been giving contradictory directions."},{"text":"Rewrite yesterday’s departure times to match the usual pickup schedule so the records look consistent.","level":0,"why":"Inventing or backdating departure times destroys the reliability of the records."},{"text":"Tell the parent that sign-out records are internal documents and refuse to discuss whether the entry is accurate.","level":0,"why":"A dismissive response avoids the concern and does nothing to resolve potentially inaccurate records."}]},"takeaway":"A coaching problem can become a records-integrity and family-trust problem. Verify the child’s safety, preserve an accurate audit trail, correct conflicting instructions, and then assess individual accountability."},"2":{"title":"A report with no timestamp","intro":"A family alleges a caregiver hurt their child at an unknown time. Video overwrites after several days.","first":{"prompt":"What is your immediate response?","options":[{"text":"Temporarily reassign the caregiver, preserve today’s footage, and wait for the family to identify a date.","level":1,"why":"Immediate protective steps help, but reasonable-suspicion reporting must not wait for a timestamp."},{"text":"Protect children, preserve all available rolling footage, and make required reports based on reasonable suspicion.","level":2,"why":"Reporting and protective measures can proceed without a private investigation or a precise timestamp."},{"text":"Have teachers question the child and classmates repeatedly until they agree on when the incident occurred.","level":0,"why":"Repeated questioning risks harm and compromises an external investigation."},{"text":"Wait for a licensing analyst before preserving the footage or contacting child protection.","level":0,"why":"Recording may overwrite, and reporting duties cannot wait for an agency visit."}]},"follow":{"lead":"The allegation remains unsubstantiated after the initial agency report. A different parent asks whether the accused caregiver will be allowed to work.","prompt":"What should the director say or do?","options":[{"text":"Tell other families the employee committed abuse so they can decide whether to withdraw.","level":0,"why":"An allegation is not a finding, and confidential personnel information requires protection."},{"text":"Maintain safe staffing but refuse to give the directly affected family any appropriate process update.","level":1,"why":"Protecting confidentiality matters, but the directly affected family may need factual safety and process information."},{"text":"Share verified safety arrangements as appropriate, maintain interim protections, and cooperate with investigators.","level":2,"why":"This balances child safety, family trust, and fair treatment of the accused employee."},{"text":"Restore unsupervised duties because the first agency contact did not lead to an immediate arrest.","level":0,"why":"A pending investigation is not proof of safety."}]},"takeaway":"Protect children, preserve recordings before overwrite, report reasonable suspicion promptly, and communicate verified facts without declaring guilt."},"3":{"title":"The clock and the ratio","intro":"A teacher is late. A second teacher suggests signing in for them so the attendance sheet shows enough coverage.","first":{"prompt":"What does the director decide?","options":[{"text":"Ask the arriving teacher to sign in at the scheduled time so the daily roster appears compliant.","level":0,"why":"False attendance records conceal rather than fix an actual staffing gap."},{"text":"Step into the room or assign qualified coverage, record actual times, and control intake if needed.","level":2,"why":"Real-time qualified coverage and accurate records come before administrative follow-up."},{"text":"Move children to the adjacent classroom without checking its current ratio.","level":1,"why":"Moving children might work, but only after verifying the receiving room has capacity and supervision."},{"text":"Ask a parent with public-school teaching experience to supervise until the employee arrives.","level":0,"why":"A credential alone does not establish clearance or eligibility to count toward ratio."}]},"follow":{"lead":"The employee arrives late again the next week, and they report a childcare transportation problem of their own.","prompt":"What longer-term response is defensible?","options":[{"text":"Allow informal recurring late arrivals and ask the opener to manage as best they can.","level":1,"why":"Flexibility is possible, but undocumented coverage gaps are not."},{"text":"Dock every opening employee’s pay whenever one colleague is late.","level":0,"why":"Collective pay penalties do not create qualified coverage and may violate wage rules."},{"text":"Set documented expectations, arrange a qualified backup, and consider a formal schedule adjustment.","level":2,"why":"The plan addresses both the employee’s barrier and the center’s daily safety obligations."},{"text":"Terminate the teacher during check-in without securing replacement coverage.","level":0,"why":"The response may create another supervision emergency."}]},"takeaway":"A schedule is not supervision. Maintain real-time ratios, keep honest records, and solve repeat attendance problems through verified staffing plans."},"4":{"title":"The child who remains at the hospital","intro":"A child is transferred to emergency care. A parent answers the phone but refuses to come to the hospital.","first":{"prompt":"What is the director’s plan?","options":[{"text":"Confirm the hospital has essential medical and contact records, maintain appropriate coordination, and document the parent’s response.","level":2,"why":"The director should support safe handoff and appropriate communication without assuming legal custody."},{"text":"Stay at the hospital indefinitely without arranging supervision back at the center.","level":1,"why":"Supporting the child is valuable, but the director must also protect the children still in care and coordinate authorized responsibilities."},{"text":"Take the child to the director’s home if the parent cannot arrive by discharge.","level":0,"why":"An informal private placement bypasses legal authority and safe discharge procedures."},{"text":"Tell hospital staff that the parent has abandoned the child and end all communication.","level":0,"why":"The facts do not establish abandonment, and the director must provide accurate information."}]},"follow":{"lead":"The parent now says they have no transportation, and the hospital is concerned about a safe discharge plan.","prompt":"What does the director do next?","options":[{"text":"Coordinate with hospital social work and the parent on a safe discharge plan, document barriers, and consult proper authorities if safety concerns meet reporting thresholds.","level":2,"why":"Practical support and appropriate escalation protect the child without making unsupported accusations."},{"text":"Arrange a verified transportation option with the parent and hospital while continuing to assess whether discharge is safe.","level":1,"why":"Transportation may solve part of the problem, but discharge safety and legal responsibility still require confirmation."},{"text":"Promise the hospital that an unapproved volunteer will sign discharge forms.","level":0,"why":"An unapproved volunteer cannot assume parental or legal consent authority."},{"text":"Make a public post naming the parent to pressure them to come to the hospital.","level":0,"why":"Public accusations violate privacy and may make the situation less safe."}]},"takeaway":"An emergency does not end at transport. Coordinate factual handoffs, preserve roles and consent authority, and solve barriers without assuming neglect from hardship alone."},"5":{"title":"The near miss becomes a pattern","intro":"The program received written reminders to secure gates and verify emergency plans. A substitute missed a critical handoff and a gate was left open.","first":{"prompt":"What director-level action is strongest?","options":[{"text":"Secure the gate, verify every child is safe, document the near miss, and address the recurring failure through accountable staff retraining and system changes.","level":2,"why":"Immediate safety measures and systemic correction are both necessary."},{"text":"Secure the gate and remind staff to sign the existing checklist before the next shift.","level":1,"why":"The immediate risk is addressed, but reminders alone may not fix the system failure."},{"text":"Increase enrollment to offset the time lost to staff retraining.","level":0,"why":"Revenue does not address the safety defect."},{"text":"Punish all employees equally so no one will admit a future near miss.","level":0,"why":"Collective blame discourages reporting and learning."}]},"follow":{"lead":"Three weeks later, the new checklist is complete, but observation shows staff routinely sign it without checking.","prompt":"How should the program evaluation respond?","options":[{"text":"Observe actual practice, redesign verification so signatures reflect completed checks, and use follow-up audits to measure compliance.","level":2,"why":"Evaluation must test behavior and safety outcomes, not merely completed paperwork."},{"text":"Add a second signature line and revisit the problem after a month.","level":1,"why":"Another signature may help accountability, but it is not evidence that the gate was checked."},{"text":"Report that training succeeded because the checklist completion rate reached 100 percent.","level":0,"why":"A completed form is not proof of safer behavior."},{"text":"Stop observing because the new paperwork demonstrates staff buy-in.","level":0,"why":"Stopping observation hides the gap between documented and actual practice."}]},"takeaway":"Evaluate what staff actually do, not what forms say they did. Use observed performance, feedback, and repeated checks to verify transfer of training."},"6":{"title":"Two reports, one standard","intro":"Two children push each other during an afternoon transition. The children's safety is checked and neither has an injury. One child's daily report describes 'difficulty sharing'; the other describes 'aggression' and recommends a temporary exclusion. You notice that the second child is Black and has been named in several earlier reports. The staff member says the child simply 'has a reputation.'","first":{"prompt":"What is the director's first leadership decision?","options":[{"text":"Preserve both reports, ask for separate observations, and check how the same safety standards were applied.","level":2,"why":"An immediate factual comparison protects children, families and staff from a conclusion based primarily on reputation."},{"text":"Introduce a shared neutral report template for future incidents and schedule a discussion about these two files.","level":1,"why":"A consistent form helps, but the current potentially unequal reports still require prompt correction and review."},{"text":"Remove the staff member from the classroom immediately because the difference proves intentional discrimination.","level":0,"why":"The disparity requires investigation, but motive and appropriate personnel action should not be presumed from the wording alone."},{"text":"Approve the recommended exclusion because a reputation supported by several prior reports is more reliable than today's observations.","level":0,"why":"Repeated records can repeat the same unsupported inference; a safety or exclusion decision requires current verified facts and applicable protections."}]},"follow":{"lead":"The teacher agrees to revise the language but still uses the same labels orally.","prompt":"What verifies a sustained change?","options":[{"text":"Review independent observations and a sample of future reports using the same behavioral standard.","level":2,"why":"Repeated, observable practice is stronger evidence than a one-time form edit."},{"text":"Ask for a signed statement that the language will improve.","level":1,"why":"Commitment is useful but is not proof of changed reporting behavior."},{"text":"Assume the problem is solved because the form is now neutral.","level":0,"why":"Written wording can change while unequal attention and consequences persist."},{"text":"Remove racial identifiers from every record even when required for appropriate data analysis.","level":0,"why":"Suppressing demographic information is not a substitute for fair decisions or responsible equity auditing."}],"takeaway":"Equal expectations require both immediate child safety and verified, consistent adult practice."}}};
function trailFeedback(option){return `<strong>${LABELS[option.level]}.</strong> ${esc(option.why)}`}
function labOptionOrder(ch,step){
 state.lab[ch]??={};
 const st=state.lab[ch],key=step===1?'firstOrder':'secondOrder';
 const count=step===1?TRAILS[ch].first.options.length:labFollow(ch,st).options.length;
 if(!Array.isArray(st[key])||st[key].length!==count||new Set(st[key]).size!==count)st[key]=shuffle(Array.from({length:count},(_,i)=>i));
 return st[key];
}
function decisionLabHtml(ch){let t=TRAILS[ch];if(!t)return '';let st=state.lab?.[ch]||{};return `<details class="decision-lab" ${st.stage?'open':''}><summary>${esc(t.title)}</summary><p>${esc(t.intro)}</p><p class="lab-instruction">Choose a response. The next situation, decision options, and consequences will depend on what you choose.</p><p><strong>${esc(t.first.prompt)}</strong></p><div class="lab-choices" id="lab-one">${labOptionOrder(ch,1).map((j,i)=>{const x=t.first.options[j];return `<button class="lab-option" type="button" aria-pressed="${st.first===j}" onclick="labChoose(${ch},1,${j})">${ABC[i]}. ${esc(x.text)}</button>`}).join('')}</div><div id="lab-reveal">${labRevealHtml(ch,st)}</div></details>`}
function labFollow(ch,st){return BRANCHING.labs[String(ch)]?.[String(st.first)] || TRAILS[ch].follow}
function labRevealHtml(ch,st){if(!st||st.first===undefined)return '';const t=TRAILS[ch],a=t.first.options[st.first],follow=labFollow(ch,st);let s=`<div class="lab-feedback ${a.level===2?'':a.level===1?'acceptable':'review'}" tabindex="-1" id="lab-feedback-one">${trailFeedback(a)}</div><div class="lab-step">Your decision changes what happens next</div><p class="branch-context">${esc(follow.lead)}</p><p><strong>${esc(follow.prompt)}</strong></p><div class="lab-choices" id="lab-two">${labOptionOrder(ch,2).map((j,i)=>{const x=follow.options[j];return `<button class="lab-option" type="button" aria-pressed="${st.second===j}" onclick="labChoose(${ch},2,${j})">${ABC[i]}. ${esc(x.text)}</button>`}).join('')}</div>`;if(st.second!==undefined){let b=follow.options[st.second];s+=`<div class="lab-feedback ${b.level===2?'':b.level===1?'acceptable':'review'}" tabindex="-1" id="lab-feedback-two">${trailFeedback(b)}<p>${esc(follow.takeaway)}</p></div>`}return s}
function labChoose(ch,step,i){const t=TRAILS[ch];if(!t||ch!==state.chapter)return;state.lab[ch]??={};const opts=step===1?t.first.options:labFollow(ch,state.lab[ch]).options;if(i<0||i>=opts.length)return;if(step===1)state.lab[ch]={first:i,stage:true,firstOrder:state.lab[ch].firstOrder};else if(state.lab[ch].first!==undefined){state.lab[ch].second=i;state.lab[ch].stage=true}else return;let box=document.getElementById('lab-reveal');if(box){box.innerHTML=labRevealHtml(ch,state.lab[ch]);document.getElementById(step===1?'lab-feedback-one':'lab-feedback-two')?.focus({preventScroll:true})}document.querySelectorAll('#lab-one .lab-option').forEach((b,j)=>b.setAttribute('aria-pressed',String(labOptionOrder(ch,1)[j]===state.lab[ch].first)));const advance=document.getElementById('labContinue');if(advance)advance.hidden=state.lab[ch].second===undefined;save()}

function lesson(){const ch=state.chapter,l=DATA.lessons[ch-1];state.phase='lesson';render(`<div class="eyebrow">Chapter ${ch} of ${CHAPTERS} · Lesson</div><h1 id="focushead">${esc(l.title)}</h1><p class="lede">${esc(l.subtitle)}</p>${ch===6?'<figure class="chapter-hero-photo"><img src="images/ch4b.webp" alt="Two young children playing with colorful building tiles in a classroom" loading="eager" decoding="async"><figcaption>Every child deserves to be seen, supported, and treated fairly.</figcaption></figure>':''}${progressHtml(ch)}<section class="card lesson"><div class="lesson-mark" aria-hidden="true">${['✦','☼','✚','⚖','♡','✧'][ch-1]||'✧'}</div>${glossary(l.html)}${workedExampleHtml(ch)}${deeperLessonHtml(ch)}${studyGuideHtml(ch)}${lensHtml(ch)}<div class="glossbox" id="glossary" role="region" aria-label="Glossary definition" tabindex="-1" hidden></div></section><div class="actions"><button class="action" onclick="continueFromLesson()">${history(ch).length||state.current?'Continue chapter decisions →':'Start Chapter '+ch+' →'}</button></div>${sourcesHtml()}`)}

function labDue(ch){
 state.labSchedule??={};
 if(state.lab?.[ch]?.second!==undefined)return false;
 if(!Number.isInteger(state.labSchedule[ch])){
  // Put each chapter's connected lab after a few randomly ordered decisions.
  state.labSchedule[ch]=Math.min(chItems(ch).length-2,3+Math.floor(Math.random()*5));
 }
 return unique(ch)>=state.labSchedule[ch];
}
function continueFromLesson(){if(state.current)return showQuestion();return question()}
function trainingLab(){const ch=state.chapter,t=TRAILS[ch];if(!t)return question();state.phase='lab';render(`<div class="eyebrow">Chapter ${ch} of ${CHAPTERS} · Branching exercise</div><h1 id="focushead">${esc(t.title)}</h1><p class="lede">Make a decision. See what happens next. Then decide again.</p><section class="card v8-training-lab">${decisionLabHtml(ch)}<div class="actions" id="labContinue" ${state.lab?.[ch]?.second===undefined?'hidden':''}><button class="action" type="button" onclick="question()">Continue to chapter questions →</button></div></section>${window.location.search.includes("embedded=1")?"":'<div class="actions"><button class="action ghost" type="button" onclick="lesson()">Back to chapter lesson</button></div>'}`);const d=document.querySelector('.v8-training-lab .decision-lab');if(d)d.open=true}
// Random order within each chapter. Revisit a topic after a weak response.
function shuffle(items){let a=items.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function complexity(q){return (q.multi?100:0)+(q.scenario||'').length/12+(q.choices||[]).reduce((s,c)=>s+c.length,0)/30}
function supportState(ch){return state.support[ch]??(state.support[ch]={active:false,correct:0,attempts:0,family:null})}
function pick(ch){
 const items=chItems(ch),h=history(ch),latest=latestResults(ch),seen=new Set(h.map(x=>x.id)),pending=state.pendingGap[ch],mode=supportState(ch);
 let pool=items.filter(q=>!seen.has(q.id));
 if(!pool.length)pool=items.filter(q=>latest[q.id]!==true);
 if(!pool.length)pool=items.slice();
 if(mode.active){
  let available=pool.filter(q=>!q.multi);
  const related=available.filter(q=>q.family===mode.family);
  if(related.length)available=related;
  if(available.length)return shuffle(available).sort((x,y)=>complexity(x)-complexity(y))[0];
 }
 if(pending){
  const related=pool.filter(q=>q.id!==pending.origin&&q.family===pending.family);
  if(related.length)pool=related;
  delete state.pendingGap[ch];
 }
 const counts={};h.forEach(e=>counts[e.id]=(counts[e.id]||0)+1);
 return shuffle(pool).sort((x,y)=>(counts[x.id]||0)-(counts[y.id]||0))[0];
}
function question(){
 state.selectedMulti=[];state.currentConcept=null;
 const ch=state.chapter;if(labDue(ch))return trainingLab();if(chapterReady(ch))return reflection();
 const q=pick(ch);state.current=q.id;state.lastAnswer=null;state.phase='question';
 if(CONCEPTS[q.family]&&!state.seenConcepts[q.family]){state.currentConcept=q.family;state.seenConcepts[q.family]=true;}
 state.guided=!!supportState(ch).active&&!q.multi;
 const all=q.choices.map((_,i)=>i);
 if(state.guided){
  const preferred=ABC.indexOf(q.answer);
  const other=shuffle(all.filter(i=>i!==preferred)).slice(0,2);
  state.order=shuffle([preferred,...other]);
 }else state.order=q.multi?all:shuffle(all);
 showQuestion();
}
function conceptCardHtml(q){
 const item=CONCEPTS[q.family];
 if(!item||state.currentConcept!==q.family)return '';
 return `<aside class="concept-card" aria-label="New idea"><div class="concept-heading"><span class="concept-kicker">NEW IDEA</span><strong>${esc(item[0])}</strong></div><p>${esc(item[1])}</p></aside>`;
}
function citeQ(q){return `<div class="scenario-references"><strong>Why this guidance?</strong> ${q.refs.map(k=>{const r=DATA.sourceMap[k];if(!r)return '';const label=r.short+(r.chaptersByChapter?`, ${r.chaptersByChapter[String(q.chapter)]||'chs. 8–9'}`:'');return r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:`<span>${esc(label)}</span>`}).filter(Boolean).join(' · ')}</div>`}
function showQuestion(){state.phase=state.lastAnswer!==null?'answered':'question';let ch=state.chapter,q=Q.find(x=>x.id===state.current);if(!q)return question();let answered=state.phase==='answered';let opt=state.order||q.choices.map((_,i)=>i),multi=!!q.multi;state.selectedMulti??=[];render(`<div class="eyebrow">Chapter ${ch} of ${CHAPTERS} · Director’s decision</div><h1 id="focushead">${esc(DATA.lessons[ch-1].title)}</h1>${progressHtml(ch)}<div class="card"><span class="tag">You are the director</span><span class="tag">${chItems(ch).length} situations in this chapter</span>${multi?'<span class="tag">Select all that apply</span>':''}${state.guided?'<span class="tag">Guided practice · Three choices</span>':''}<h2>${glossary(esc(q.scenario))}</h2>${conceptCardHtml(q)}<p>${multi?'Choose ALL necessary or defensible actions. More than one answer is correct; do not select actions that undermine safety or fairness.':'Which response is the strongest initial supervisory decision? A second response may also be defensible with conditions.'}</p>${!answered?decisionGuideHtml(ch):''}<div class="choices">${opt.map((j,i)=>{let L=ABC[j],sel=multi&&state.selectedMulti.includes(L);return `<button class="choice ${sel?'chosen':''}" id="opt${i}" data-letter="${L}" ${multi?`aria-pressed="${sel}" onclick="toggleMulti('${L}')"`:`onclick="answer('${L}')"`} ${answered?'disabled':''}><span class="letter">${multi?(sel?'✓':'□'):ABC[i]}</span><span>${esc(q.choices[j])}</span></button>`}).join('')}</div>${multi&&!answered?'<div class="actions"><button class="action" onclick="submitMulti()">Evaluate selected actions</button></div>':''}<div id="response" aria-live="polite"></div><div class="glossbox" id="glossary" role="region" tabindex="-1" aria-label="Term definition" hidden></div></div><details id="chapter-review"><summary>Review the chapter lesson</summary><div class="lesson">${glossary(DATA.lessons[ch-1].html)}${deeperLessonHtml(ch)}${studyGuideHtml(ch)}${lensHtml(ch)}</div><div class="glossbox" id="glossary" role="region" aria-label="Glossary definition" tabindex="-1" hidden></div></details>`);if(answered)showFeedback(q,state.lastAnswer)}
function gradeResponse(q,selection){if(q.multi){let selected=selection?selection.split('|').filter(Boolean):[];let gold=q.answerSet;return selected.length===gold.length&&selected.every(x=>gold.includes(x))?2:(selected.length&&selected.every(x=>gold.includes(x))?1:0)}return selection===q.answer?2:(q.acceptable&&q.acceptable[selection]?1:0)}
function recordResponse(q,selection){let ch=state.chapter,quality=gradeResponse(q,selection),ok=q.multi?quality===2:quality>0;state.lastAnswer=selection;state.phase='answered';(state.history[ch]??=[]).push({id:q.id,correct:ok,quality,option:selection});
 const mode=supportState(ch);
 if(ok){state.streak[ch]=0;if(mode.active){mode.correct++;mode.attempts++;if(mode.correct>=2){mode.active=false;mode.correct=0;mode.attempts=0;mode.family=null}}}
 else{state.streak[ch]=(state.streak[ch]||0)+1;if(mode.active){mode.correct=0;mode.attempts++}if(state.streak[ch]>=2){mode.active=true;mode.correct=0;mode.family=q.family}}
 if(FOLLOWUPS[q.id]&&!state.branchDone[q.id])state.branchPending={id:q.id,quality,chapter:ch,selected:null};
 if(!ok){let fam=q.family;(state.wrongTags[ch]??={})[fam]=((state.wrongTags[ch]||{})[fam]||0)+1;state.pendingGap[ch]={family:fam,origin:q.id}}showFeedback(q,selection);if(q.multi)document.querySelector('button[onclick="submitMulti()"]')?.parentElement?.remove();nav();let p=document.querySelector('.chapterprogress');if(p)p.outerHTML=progressHtml(ch);save()}
function answer(letter){if(state.phase!=='question'||state.lastAnswer!==null)return;recordResponse(Q.find(x=>x.id===state.current),letter)}
function toggleMulti(letter){if(state.phase!=='question'||state.lastAnswer!==null)return;state.selectedMulti??=[];state.selectedMulti=state.selectedMulti.includes(letter)?state.selectedMulti.filter(x=>x!==letter):[...state.selectedMulti,letter].sort();document.querySelectorAll('.choice').forEach(el=>{let sel=state.selectedMulti.includes(el.dataset.letter);el.setAttribute('aria-pressed',sel?'true':'false');el.classList.toggle('chosen',sel);el.querySelector('.letter').textContent=sel?'✓':'□'});save()}
function submitMulti(){if(state.phase!=='question'||state.lastAnswer!==null)return;if(!state.selectedMulti?.length){let r=document.getElementById('response');r.innerHTML='<p class="note" role="alert">Choose one or more actions before evaluating.</p>';return}recordResponse(Q.find(x=>x.id===state.current),state.selectedMulti.join('|'))}
function showFeedback(q,selection){let quality=gradeResponse(q,selection),ch=state.chapter,multi=!!q.multi,sel=multi?selection.split('|'): [selection],gold=multi?q.answerSet:[q.answer];document.querySelectorAll('.choice').forEach(el=>{el.disabled=true;let v=el.dataset.letter;el.classList.toggle('chosen',sel.includes(v));el.classList.toggle('preferred',gold.includes(v));});let text='';if(multi){let missing=gold.filter(x=>!sel.includes(x)),extras=sel.filter(x=>!gold.includes(x));let lines=gold.map(k=>`<li><strong>${k}.</strong> ${esc(q.choices[ABC.indexOf(k)])}</li>`).join('');let reasons=sel.map(k=>`<li><strong>${k}.</strong> ${esc(q.feedback?.[k]?.text||'Review the option against the stated duties.')}</li>`).join('');text=`<p>${quality===2?'You selected every supported action and avoided the harmful alternatives.':quality===1?'Your choices are defensible, but incomplete. A director needs the whole response.':'Some selections are unsafe or unnecessary, or key actions are missing.'}</p>${missing.length?`<p><strong>Missing:</strong> ${missing.join(', ')}</p>`:''}${extras.length?`<p><strong>Reconsider:</strong> ${extras.join(', ')}</p>`:''}<p><strong>Your selected actions, explained:</strong></p><ul>${reasons}</ul><p><strong>Supported actions:</strong></p><ul>${lines}</ul><p>${esc(q.rationale)}</p>`}else{text=quality===2?`<p><strong>Why your chosen action is supported:</strong> ${esc(q.feedback?.[q.answer]?.text||q.rationale)}</p><p><strong>The governing principle:</strong> ${esc(q.rationale)}</p><p><strong>Apply this elsewhere:</strong> ${esc(DEEPER_LESSONS[ch]?.question||'What would you do if the circumstances changed?')}</p>`:quality===1?`<p><strong>Your choice:</strong> ${esc(q.choices[ABC.indexOf(selection)])}</p><p>${esc(q.acceptable[selection])}</p><p><strong>More complete response:</strong> ${esc(q.choices[ABC.indexOf(q.answer)])}</p><p>${esc(q.rationale)}</p>`:`<p><strong>Your choice:</strong> ${esc(q.choices[ABC.indexOf(selection)])}</p><p>${esc(q.feedback[selection]?.text||'This approach leaves a critical gap.')}</p><p><strong>Stronger response:</strong> ${esc(q.choices[ABC.indexOf(q.answer)])}</p><p>${esc(q.rationale)}</p>`}let refHtml=citeQ(q);document.getElementById('response').innerHTML=`<div class="feedback ${quality===2?'':quality===1?'acceptable':'review'}" role="status" tabindex="-1"><h3>${quality===2?'A well-supported decision':quality===1?'Defensible, with conditions':'Consider the consequences'}</h3>${text}${refHtml}</div><div class="actions"><button class="action secondary" type="button" onclick="openStudyGuideFor(\'${q.id}\')">Review the chapter explanation: ${esc(topicForQuestion(q.id)?.title||"Relevant principle")}</button><button class="action" onclick="nextDecision()">${chapterReady(ch)?'Continue':'Next supervisory decision'}</button></div>`;document.querySelector('#response .feedback')?.focus({preventScroll:true});save()}
function nextDecision(){if(state.branchPending&&state.branchPending.chapter===state.chapter)return branchQuestion();return question()}
function branchQuestion(){
 const pending=state.branchPending;if(!pending)return chapterReady(state.chapter)?reflection():question();
 const node=FOLLOWUPS[pending.id];if(!node){state.branchPending=null;return question()}
 state.phase='followup';
 const selected=pending.selected;
 pending.order??=shuffle(node.options.map((_,i)=>i));
 const lead=pending.quality===2?node.correctLead:node.repairLead;
 render(`<div class="eyebrow">Chapter ${state.chapter} · What happens next?</div><h1 id="focushead">The situation continues</h1><p class="lede">${esc(lead)}</p><section class="card"><p><strong>${esc(node.prompt)}</strong></p><div class="choices">${pending.order.map((j,i)=>{const option=node.options[j];return `<button class="choice ${selected===j?'chosen':''}" type="button" onclick="chooseQuestionBranch(${j})" ${selected!==null?'disabled':''}><span class="letter">${ABC[i]}</span><span>${esc(option.text)}</span></button>`}).join('')}</div>${selected!==null?`<div class="feedback ${node.options[selected].level===2?'':node.options[selected].level===1?'acceptable':'review'}" role="status"><h3>${node.options[selected].level===2?'Strong follow-through':node.options[selected].level===1?'A partial response':'Consider the consequences'}</h3><p>${esc(node.options[selected].text)}</p><p>${node.options[selected].level===2?'You addressed the new risk and followed up with a defensible plan.':node.options[selected].level===1?'Part of the response helps, but important follow-up remains.':'This response creates or leaves a serious problem unresolved.'}</p>${node.options[selected].level<2?`<p><strong>A stronger approach:</strong> ${esc(node.options[0].text)}</p>`:''}</div>${followupTeachingHtml(node,selected,pending.id)}<div class="actions"><button class="action" type="button" onclick="continueAfterBranch()">Next supervisory decision</button></div>`:''}</section>${citeQ(Q.find(q=>q.id===pending.id))}`);
}
function chooseQuestionBranch(i){
 const p=state.branchPending;if(!p||p.selected!==null)return;
 const n=FOLLOWUPS[p.id];if(!n||!n.options[i])return;
 p.selected=i;state.branchDone[p.id]=true;branchQuestion();
}
function continueAfterBranch(){
 const p=state.branchPending;if(!p||p.selected===null)return;
 state.branchPending=null;
 return question();
}
const samples=[["“I hear what you said. While I arrange coverage, I need to understand what you meant, what has happened during supervision, and whether every child can be cared for safely.”","Do not substitute either automatic dismissal or casual reassurance for a documented safety and personnel review."],["“We will respond to what was observed, keep the child safe, make any required report and preserve records. We will not treat poverty as proof of abuse.”","Avoid private detective work before reporting and avoid assuming homelessness alone is neglect."],["“Our actual roster has to meet the rule right now. I will cover or adjust intake, then correct the schedule and document that we are compliant.”","Never confuse a posted staff schedule with physically present qualified coverage."],["“Here is the factual timeline and the child’s care plan. Who at the hospital is coordinating a safe discharge, and who are our authorized contacts?”","Do not assume that a parent’s refusal automatically proves neglect, or that the director gains parental medical authority."],["“We need to observe the real process, assign corrective ownership, and verify the change; signing another checklist is not proof of safety.”","A quiz or training attendance record is not evidence of reliable skill transfer."]];

function reflection(){let ch=state.chapter,l=DATA.lessons[ch-1];state.phase='reflection';render(`<div class="eyebrow">Chapter ${ch} · Applied reflection</div><h1 id="focushead">Put it into supervisory practice</h1>${progressHtml(ch)}<div class="card"><p>You have worked through this chapter's situations. Before moving on, consider how you would apply the ideas as a director with your staff, children or families.</p>${state.needsWorkshop[ch]?'<div class="note">Some decisions deserve conversation and live rehearsal. Bring a question from this chapter to your next workshop or coaching conversation.</div>':''}<h2>${esc(l.title)}</h2><p>Identify a caregiving situation. What action would you take as director? What law or policy would you verify, whom would you consult, and how would you measure follow-through?</p><label for="reflection">Your plan or opening words</label><textarea id="reflection" oninput="saveReflection(this.value)" placeholder="A situation I could face is…">${esc(state.reflection[ch]||'')}</textarea>${state.refReviewed[ch]?"":'<div class="actions" id="reflectionCompareAction"><button class="action" onclick="compareReflection()">Compare with a director response →</button></div>'}<div id="reflectionHelp" role="region" aria-label="Reflection comparison" tabindex="-1" aria-live="polite">${state.refReviewed[ch]?sampleHtml(ch):''}</div>${state.refReviewed[ch]?`<div class="actions"><button class="action" onclick="finishChapter()">Complete chapter and review submission</button></div>`:''}</div>`)}
