function compareReflection(){let el=document.getElementById('reflection'),v=el?.value.trim();if(!v){el.focus();return}saveReflection(el.value);state.refReviewed[state.chapter]=true;document.getElementById('reflectionHelp').innerHTML=sampleHtml(state.chapter);document.getElementById('reflectionCompareAction')?.remove();let actions=document.getElementById('reflectionHelp').nextElementSibling;if(!actions){document.getElementById('reflectionHelp').insertAdjacentHTML('afterend','<div class="actions"><button class="action" onclick="finishChapter()">Complete chapter and review submission</button></div>')}document.getElementById('reflectionHelp')?.focus({preventScroll:true});save()}
function finishChapter(){
 const ch=state.chapter;
