function capstoneStage(i,c){if(i===0)return FINAL_CHALLENGE[0];const previous=c?.choices?.[i-1];return CAPSTONE_BRANCHES[String(i)]?.[String(previous)] || FINAL_CHALLENGE[i]}
function capstoneOptionOrder(i,c,q){
 c.displayOrder??={};
 const key=String(i),order=c.displayOrder[key];
 if(!Array.isArray(order)||order.length!==q.choices.length||new Set(order).size!==q.choices.length)
  c.displayOrder[key]=shuffle(q.choices.map((_,j)=>j));
 return c.displayOrder[key];
