function capstone(){if(!allChaptersComplete())return resume();const c=ensureCapstone();if(c.completed){state.phase='finished';return finish()};state.phase='capstone';const i=Math.min(c.step,FINAL_CHALLENGE.length);if(i>=FINAL_CHALLENGE.length)return capstoneReflection();const q=capstoneStage(i,c),sel=c.choices[i];const progress=FINAL_CHALLENGE.map((_,j)=>`<span class="capstone-dot ${j<i?'done':j===i?'active':''}" aria-hidden="true"></span>`).join('');render(`<div class="eyebrow">Final challenge · Decisions with consequences</div><h1 id="focushead">When the director’s plans meet real life</h1><p class="lede">Every decision changes the next challenge. Even the strongest first response can be followed by an unexpected complication.</p><div class="capstone-step">Decision ${i+1} of ${FINAL_CHALLENGE.length}</div><div class="capstone-progress" aria-label="Final challenge progress">${progress}</div><section class="card"><h2>${esc(q.head)}</h2><div class="capstone-context">${i>0?`<p class="branch-path-label">NEW DEVELOPMENT · Based on your previous choice</p>`:''}<p>${esc(q.lead)}</p></div><p><strong>${esc(q.question)}</strong></p><div class="capstone-options">${capstoneOptionOrder(i,c,q).map((j,displayIndex)=>{const o=q.choices[j];return `<button type="button" class="capstone-option ${sel===j?'chosen':''}" aria-pressed="${sel===j}" onclick="chooseCapstone(${j})" ${sel!==undefined?'disabled':''}><strong>${ABC[displayIndex]}.</strong> ${esc(o[0])}</button>`}).join('')}</div>${sel!==undefined?`<div class="capstone-feedback ${capstoneScore(i,c)===2?'':capstoneScore(i,c)===1?'acceptable':'review'}" role="status" tabindex="-1" id="capstoneFeedback"><strong>${LABELS[capstoneScore(i,c)]}</strong><p>${esc(q.choices[sel][1])}</p><p class="meta">Your decision will alter the next event and available responses.</p></div><div class="actions"><button class="action" onclick="nextCapstone()">${i===FINAL_CHALLENGE.length-1?'Review your decision trail':'See the consequence'}</button></div>`: