function returnHome(){go("overview");}
function startOverTraining(){
 if(!window.confirm("Start the ENTIRE training over? This clears your chapter answers, case decisions, assessments, certificate completion date, and locally queued reports for this learner. Continue?"))return;
 try {
  for(const store of [localStorage,sessionStorage]){
   store.removeItem(KEY);
   store.removeItem("care-with-a-compass-supervisor-v72-72q");
   store.removeItem("cwc-consequence-lab-v10");
   store.removeItem("cwc-consequence-lab-completed");
   store.removeItem("cwc-consequence-lab-guided-v10");
  }
 }catch(err){window.alert("Could not clear your saved progress in this browser. Your training has not been restarted.");return;}
 window.CWC_LEARNER?.resetProgress();
 window.CWC_BUDGET?.reset();
 state=initial();facilitatorDemoUnlocked=false;
 render();
 window.scrollTo({top:0,behavior:"auto"});
}
function go(page){if(!canOpen(page))return;if(page==="chapters")pendingChapterJump=null;if(window.CWC_LEARNER&&!window.CWC_LEARNER.ready()&&page!=="chapters")page="overview";if(page==="cases"&&!canOpenCase(state.caseId))state.caseId=D.cases[0].id;state.page=page;save();render();window.scrollTo({top:0,behavior:"auto"});}
function download(name,body,type){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function report(){
 const a=state.assessment,r=assessScores();
 return {application:"Care with a Compass",version:"10.7.4",generatedAt:new Date().toISOString(),participant:a.name||"Anonymous local participant",scores:{diagnostic:r.partA,capstone:r.partB,transfer:r.manual,total:r.manual===null?null:r.total},mastery:{objective1:r.skillCorrect,objective4:r.causeCorrect,criticalSafetyErrors:r.critical,provisionalStatus:r.manual===null?"facilitator review pending":r.pass?"all pilot gates met":"remediation required"},responses:{diagnostic:a.diagnostic,capstone:a.capstone,transferPlan:a.transfer},facilitator:{reviewer:a.reviewer,notes:a.facilitatorNote,reviewMode:"Unverified local scoring simulation"},warning:"This browser cannot authenticate the scorer, verify first attempts, or issue an accredited/verified competency credential."};
}
function csv(x){return '"'+String(x??"").replace(/"/g,'""')+'"';}
document.addEventListener("submit",e=>{if(e.target?.id!=="cwc-learner-form")return;e.preventDefault();if(window.CWC_LEARNER?.enroll()){state.assessment.name=window.CWC_LEARNER.profile().name;save();resumeLinear();}});
document.addEventListener("click",e=>{
 const btn=e.target.closest("button[data-action]");if(!btn)return;
 const action=btn.dataset.action;
 if(action==="term"){const wasOpen=btn.getAttribute("aria-expanded")==="true";hideDefinitions();if(!wasOpen)btn.setAttribute("aria-expanded","true");return;}
 if(action==="complete-lesson"){const key=moduleKey();if(!L.modules?.[key])return;state.introSeen[key]=true;save();return render();}
 if(action==="print-completion-certificate")return window.CWC_LEARNER?.certificatePrint(state,courseReady(),allCasesDone());
 if(action==="enable-facilitator-demo"){if(!state.assessment.submitted)return;facilitatorDemoUnlocked=true;return render();}
 if(action==="start-training"){if(window.CWC_LEARNER&&!window.CWC_LEARNER.ready()){go("overview");$("#cwc-name")?.focus();return;}return resumeLinear();}
 if(action==="home")return returnHome();
 if(action==="start-over")return startOverTraining();
 if(action==="switch-learner"){if(!window.confirm("Switch learner? This clears all course progress, reports awaiting delivery, and the previous learner\'s certificate from this browser. Continue?"))return;try{for(const store of [localStorage,sessionStorage]){store.removeItem(KEY);store.removeItem("care-with-a-compass-supervisor-v72-72q");}}catch(e){}window.CWC_LEARNER?.forgetLearner();window.CWC_BUDGET?.reset();state=initial();facilitatorDemoUnlocked=false;return render();}
 if(action==="journey-next")return continueJourney();
 if(action==="review-lesson"){const key=moduleKey();delete state.introSeen[key];save();return render();}
 if(action==="nav")return go(btn.dataset.page);
 if(action==="simulation-mode"){if(!["random","guided"].includes(btn.dataset.mode))return;state.simulationMode=btn.dataset.mode;save();return render();}
  if(action==="enter-cases")return go("cases");
 if(action==="go-chapters")return go("chapters");
 if(action==="go-staff")return go("staff");
 if(action==="go-evidence")return go("evidence");
 if(action==="go-assessment")return go("assessment");
 if(action==="go-facilitator")return go("facilitator");
 if(action==="open-case"){if(!canOpenCase(btn.dataset.id))return;state.caseId=btn.dataset.id;return go("cases");}
 if(action==="case-answer"){
  const c=getCase(state.caseId),w=work(c.id);if(w.step>=c.stages.length||w.chosen[w.step])return;
  if(!optionFor(caseStage(c,w.step),btn.dataset.option))return;
  w.chosen[w.step]=btn.dataset.option;save();return render();
 }
 if(action==="case-next"){const c=getCase(state.caseId),w=work(c.id);if(!w.chosen[w.step])return;w.step=Math.min(w.step+1,c.stages.length);save();return render();}
 if(action==="reset-case"){if(!window.confirm("Restart this scenario and clear its local decision trail?"))return;state.caseWork[state.caseId]={step:0,chosen:[]};save();return render();}
 if(action==="review-evidence"){if(D.evidence.some(x=>!state.evidence[x.id]))return;state.evidenceReviewed=true;save();return render();}
 if(action==="reset-evidence"){state.evidence={};state.evidenceReviewed=false;save();return render();}
 if(action==="export-case"){const c=getCase(state.caseId),w=work(c.id);if(w.step<c.stages.length)return;const record={application:"Care with a Compass",version:D.version,caseTitle:c.title,startingConditions:selectedVariant(c).label,generatedAt:new Date().toISOString(),decisionTrail:w.chosen.map((id,i)=>{const active=caseStage(c,i),o=optionFor(active,id);return {stage:active.title,scenario:active.lead,question:active.question,decision:o.text,feedback:o.feedback,consequence:o.consequence,criticalSafetyConcern:o.critical}}),facilityConditions:caseConditions(c,w),notice:"Fictional local practice; not a professional competency certificate."};return download("CWC_v1070_"+c.id+"_Decision_Trail.json",JSON.stringify(record,null,2),"application/json;charset=utf-8");}
 if(action==="revise-capstone"){const idx=Number(btn.dataset.stage);if(!Number.isInteger(idx)||idx<0||idx>=D.assessment.stages.length||state.assessment.submitted)return;for(let j=idx;j<D.assessment.stages.length;j++)delete state.assessment.capstone[D.assessment.stages[j].title];save();render();document.getElementById("capstone-active")?.scrollIntoView({block:"start",behavior:"auto"});return;}
 if(action==="submit-assessment"){if(!assessmentReady())return;state.assessment.submitted=true;state.assessment.facilitatorScore=null;state.assessment.name=window.CWC_LEARNER?.profile()?.name||"";save();window.CWC_LEARNER?.assessmentSubmitted(report());return go("facilitator");}
 if(action==="reset-assessment"){if(!window.confirm("Clear this local practice assessment, including facilitator feedback?"))return;state.assessment=initial().assessment;facilitatorDemoUnlocked=false;save();return render();}
 if(action==="save-review"){
  if(!facilitatorDemoUnlocked||!state.assessment.submitted)return;
  const input=$("#transferScore"),score=input?.value.trim(),note=$("#reviewNote")?.value||"",reviewer=$("#reviewer")?.value||"";
  if(!/^(10|[0-9])$/.test(score||"")){window.alert("Enter a whole-number transfer score between 0 and 10.");return;}
  state.assessment.facilitatorScore=Number(score);state.assessment.facilitatorNote=note;state.assessment.reviewer=reviewer;save();window.CWC_LEARNER?.facilitatorReviewed(report());return render();
 }
 if(action==="export-json"){if(!state.assessment.submitted)return;return download("Care_with_a_Compass_v1070_Assessment_Report.json",JSON.stringify(report(),null,2),"application/json;charset=utf-8");}
 if(action==="export-csv"){if(!state.assessment.submitted)return;const r=report(),s=r.scores,m=r.mastery;const fields=["version","participant","diagnostic","capstone","transfer","total","objective1","objective4","criticalSafetyErrors","status","reviewer"];const values=[r.version,r.participant,s.diagnostic,s.capstone,s.transfer,s.total,m.objective1,m.objective4,m.criticalSafetyErrors,m.provisionalStatus,r.facilitator.reviewer];return download("Care_with_a_Compass_v1070_Assessment_Summary.csv",fields.map(csv).join(",")+"\n"+values.map(csv).join(",")+"\n","text/csv;charset=utf-8");}
 if(action==="print")return window.print();
});
document.addEventListener("keydown",e=>{if(e.key==="Escape")hideDefinitions();});
 document.addEventListener("change",e=>{
 const el=e.target,type=el.dataset.change;if(!type)return;
 if(type==="variant-select"){if(state.variants[state.caseId]!==el.value&&work(state.caseId).chosen.length&&!window.confirm("Switching starting conditions restarts this scenario. Continue?"))return render();state.variants[state.caseId]=el.value;state.caseWork[state.caseId]={step:0,chosen:[]};}
 else if(type==="staff-plan"){state.staffing.plan=el.value;state.sequence.staffTouched=true;}
 else if(type==="staff-shock"){state.staffing.disruption=el.value;state.sequence.staffTouched=true;}
 else if(type==="staff-wage"){state.staffing.wage=Math.max(18,Math.min(45,Number(el.value)||23));state.sequence.staffTouched=true;}
 else if(type==="staff-attendance"){state.staffing.attendance=Math.max(6,Math.min(36,Number(el.value)||12));state.sequence.staffTouched=true;}
 else if(type==="staff-teachers"){state.staffing.qualifiedTeachers=Math.max(1,Math.min(4,Number(el.value)||1));state.sequence.staffTouched=true;}
 else if(type==="staff-window"){state.staffing.window=el.value;state.sequence.staffTouched=true;}
 else if(type==="staff-support"){state.staffing.support=el.value;state.sequence.staffTouched=true;}
 else if(type==="evidence"){if(!state.evidenceReviewed)state.evidence[el.dataset.id]=el.value;}
 else if(type==="diagnostic-skill"||type==="diagnostic-cause"){state.assessment.diagnostic[el.dataset.id]??={};state.assessment.diagnostic[el.dataset.id][type==="diagnostic-skill"?"skill":"cause"]=el.value;}
 else if(type==="capstone"){
   const idx=D.assessment.stages.findIndex(s=>s.title===el.dataset.stage);
   const selected=assessmentStage(idx,state.assessment.capstone);
   if(idx<0||!selected.options.some(o=>o.id===el.value))return;
   state.assessment.capstone[el.dataset.stage]=el.value;
   for(let j=idx+1;j<D.assessment.stages.length;j++)delete state.assessment.capstone[D.assessment.stages[j].title];
   save();render();document.getElementById("capstone-active")?.scrollIntoView({block:"start",behavior:"auto"});return;
  }
 else if(type==="assess-name"){state.assessment.name=el.value;}
 else return;
 save();render();
});
document.addEventListener("cwc-budget-changed",()=>{
 const progress=overallProgress(),bar=document.querySelector(".course-progress-track"),fill=bar?.querySelector("span"),label=document.getElementById("cwc-progress-text");
 if(bar)bar.setAttribute("aria-valuenow",String(progress.percent));
 if(fill)fill.style.width=progress.percent+"%";
 if(label)label.textContent=progress.percent+"% complete · "+progress.chapters+" of 6 chapters";
 const next=document.querySelector('button[data-action="journey-next"]');
 if(next&&state.page==="staff")next.disabled=!state.sequence.staffTouched;
});
document.addEventListener("input",e=>{
 if(e.target?.dataset?.change==="staff-wage"){
  state.staffing.wage=Math.max(18,Math.min(45,Number(e.target.value)||23));
  state.sequence.staffTouched=true;
  save();
  refreshStaffBudgetPreview();
  return;
 }
 if(e.target?.dataset?.change==="assess-transfer"){state.assessment.transfer=e.target.value;save();const count=$("assessTransferCount");if(count)count.textContent=state.assessment.transfer.trim().length+"/40 characters minimum";const button=$('button[data-action="submit-assessment"]');if(button)button.disabled=!assessmentReady();}
});
window.addEventListener('storage',e=>{if(e.key==='cwc-consequence-lab-v10'&&completedLabFromStorage()&&!state.completedSimulations.random){state.completedSimulations.random=true;save();render();}});
window.addEventListener("message",e=>{const frame=document.getElementById("consequenceLabFrame");if(!frame||e.source!==frame.contentWindow||e.origin!==window.location.origin||e.data?.app!=="cwc-consequence-lab")return;if(e.data.kind==="lab-completed"){if(e.data.completed===true&&e.data.mode==="unified"){state.completedSimulations.random=true;save();}return;}if(e.data.kind!=="lab-height")return;const h=Number(e.data.height);if(Number.isFinite(h)&&h>200)frame.style.height=Math.min(30000,Math.ceil(h+20))+"px";});
 window.addEventListener("message",e=>{const frame=document.getElementById("chaptersFrame");if(!frame||e.source!==frame.contentWindow||e.origin!==window.location.origin)return;const data=e.data;if(data?.app!=="care-with-a-compass")return;if(data.kind==="chapter-progress"){const numbers=Array.isArray(data.done)?[...new Set(data.done.filter(n=>Number.isInteger(n)&&n>=1&&n<=6))]:[];const badge=document.getElementById("chapterCompletedCount");if(badge)badge.textContent=numbers.length+"/6 completed";return;}
if(data.kind==="chapter-submit-request"){
 const payload=data.payload||{},ch=Number(payload.chapter);
 const actual=courseProgress().done;
 if(!window.CWC_LEARNER?.ready()||!Number.isInteger(ch)||ch<1||ch>6||actual<1){return;}
 Promise.resolve(window.CWC_LEARNER.submitChapter(payload)).then(status=>{
  if(frame.contentWindow===e.source)frame.contentWindow.postMessage({app:"care-with-a-compass",kind:"chapter-submit-status",chapter:ch,status,error:status==="sent"?"":(window.CWC_LEARNER.reportError(ch)||"")},window.location.origin);
 }).catch(()=>{
  if(frame.contentWindow===e.source)frame.contentWindow.postMessage({app:"care-with-a-compass",kind:"chapter-submit-status",chapter:ch,status:"failed",error:"The result could not be confirmed. Check Formspree submissions before retrying."},window.location.origin);
 });
 return;
}if(data.kind==="course-height"&&Number.isFinite(Number(data.height))){const wanted=Math.max(240,Math.min(25000,Math.ceil(Number(data.height)+10)));if(Math.abs(frame.getBoundingClientRect().height-wanted)>2)frame.style.height=wanted+"px";}});
if(!canOpen(state.page))state.page="overview";
 if(state.page==="cases"&&!canOpenCase(state.caseId))state.caseId=D.cases[0].id;
 render();
})();
